#nullable enable // autogenerated

using System;
using System.IO;
using System.Linq;
using UnityEngine;

namespace MVZ2.Sprites
{
    public static class SpriteHelper
    {
        public static void SaveToPath(this Texture2D texture, string path)
        {
            var bytes = texture.EncodeToPNG();
            using (var stream = File.Open(path, FileMode.Create))
            {
                using (var writer = new BinaryWriter(stream))
                {
                    writer.Write(bytes);
                }
            }
        }
        /// <summary>
        /// 修复图片导入时白边问题
        /// </summary>
        /// <param name="texture"></param>
        public static void FixTransparency(this Texture2D texture)
        {
            Color32[] pixels = texture.GetPixels32();
            int w = texture.width;
            int h = texture.height;

            for (int y = 0; y < h; y++)
            {
                for (int x = 0; x < w; x++)
                {
                    FixTransparencyPixel(pixels, x, y, w, h);
                }
            }

            texture.SetPixels32(pixels);
            texture.Apply();
        }
        private static void FixTransparencyPixel(Color32[] pixels, int x, int y, int w, int h)
        {
            int idx = y * w + x;
            Color32 pixel = pixels[idx];
            if (pixel.a != 0)
                return;
            for (int i = 0; i < 8; i++)
            {
                var offset = surroundingOffsets[i];
                var adjX = x + offset.x;
                var adjY = y + offset.y;
                if (adjX >= 0 && adjX < w && adjY >= 0 && adjY < h)
                {
                    var adjIndex = adjY * w + adjX;
                    var adjacent = pixels[adjIndex];
                    if (adjacent.a != 0)
                    {
                        pixel.r = adjacent.r;
                        pixel.g = adjacent.g;
                        pixel.b = adjacent.b;
                        break;
                    }
                }
            }
            pixels[idx] = pixel;
        }
        public static void GetPixels32(this Color32[] allPixels, int texWidth, int x, int y, int width, int height, Color32[] buffer)
        {
            for (int row = 0; row < height; row++)
            {
                int sourceIndex = (y + row) * texWidth + x;
                int targetIndex = row * width;
                Array.Copy(allPixels, sourceIndex, buffer, targetIndex, width);
            }
        }
        public static void FlipColors(this Texture2D texture)
        {
            var colors = texture.GetPixels32();
            var width = texture.width;
            var height = texture.height;

            Color32[] tempRow = new Color32[width];
            for (int y = 0; y < height / 2; y++)
            {
                int topRowIndex = y * width;
                int bottomRowIndex = (height - y - 1) * width;

                // 交换顶部和底部的像素行
                Array.Copy(colors, topRowIndex, tempRow, 0, width);
                Array.Copy(colors, bottomRowIndex, colors, topRowIndex, width);
                Array.Copy(tempRow, 0, colors, bottomRowIndex, width);
            }

            texture.SetPixels32(colors);
        }
        public static string GetLanguageSpriteTag(string languageCode)
        {
            return languageCode;
        }
        public static void ParseIDAndTags(string path, out string id, out string[] tags)
        {
            var splitTagTexturePaths = path.Split("@");
            id = splitTagTexturePaths[0];
            tags = splitTagTexturePaths.Skip(1).ToArray();
        }
        public static int FromBottomToFromTopY(int fromBottomY, int textureHeight, int rectHeight)
        {
            return textureHeight - fromBottomY - rectHeight;
        }
        public static int FromTopToFromBottomY(int fromTopY, int textureHeight, int rectHeight)
        {
            return textureHeight - fromTopY - rectHeight;
        }
        public static float FromBottomToFromTopY(float fromBottomY, float textureHeight, float rectHeight)
        {
            return textureHeight - fromBottomY - rectHeight;
        }
        public static float FromTopToFromBottomY(float fromTopY, float textureHeight, float rectHeight)
        {
            return textureHeight - fromTopY - rectHeight;
        }
        public static float FromBottomToFromTopPivotY(float pivotY)
        {
            return 1 - pivotY;
        }
        public static float FromTopToFromBottomPivotY(float pivotY)
        {
            return 1 - pivotY;
        }
        public const string SPRITE_TAG_CENSORED = "censored";
        public static readonly Vector2Int[] surroundingOffsets = new Vector2Int[]
        {
            new Vector2Int(1, 0),           // Right
            new Vector2Int(1, -1),          // Bottom Right
            new Vector2Int(0, -1),          // Bottom
            new Vector2Int(-1, -1),         // Bottom Left
            new Vector2Int(-1, 0),          // Left
            new Vector2Int(-1, 1),          // Top Left
            new Vector2Int(0, 1),           // Top
            new Vector2Int(1, 1),           // Top Right
        };
    }
}
